package com.example.discussions;import com.example.discussions.controller.AuthController;import com.example.discussions.dto.Requests.*;import com.example.discussions.model.User;import com.example.discussions.repository.UserRepository;import com.example.discussions.security.JwtService;import org.junit.jupiter.api.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;class AuthControllerTest{@Test void returnsTokenForValidCredentials(){var users=mock(UserRepository.class);var encoder=mock(PasswordEncoder.class);var jwt=mock(JwtService.class);var u=new User();u.username="alice";u.passwordHash="hash";when(users.findByUsernameIgnoreCase("alice")).thenReturn(Optional.of(u));when(encoder.matches("password",u.passwordHash)).thenReturn(true);when(jwt.create("alice")).thenReturn("token");var response=new AuthController(users,encoder,jwt).login(new Login("alice","password"));assertEquals("token",response.token());}}
